const scrollables = await browserjs(tabId, () => {
  const all = Array.from(document.querySelectorAll('*'));
  return all.filter(el => {
    const style = window.getComputedStyle(el);
    const hasScroll = (el.scrollWidth > el.clientWidth && (style.overflowX === 'scroll' || style.overflowX === 'auto')) ||
                      (el.scrollHeight > el.clientHeight && (style.overflowY === 'scroll' || style.overflowY === 'auto'));
    return hasScroll && el.clientWidth > 100;
  }).map(el => ({
    tagName: el.tagName,
    id: el.id,
    className: el.className,
    scrollWidth: el.scrollWidth,
    clientWidth: el.clientWidth,
    scrollHeight: el.scrollHeight,
    clientHeight: el.clientHeight
  }));
});
