const tabId = 1962625075;

// Let's scroll down step by step and collect all unique items
const items = await browserjs(tabId, async () => {
  const collected = new Map();

  function record() {
    const renderers = document.querySelectorAll('ytk-compact-video-renderer, ytk-compact-playlist-renderer, ytk-compact-channel-renderer, ytk-compact-show-renderer');
    renderers.forEach(el => {
      const title = el.querySelector('#video-title, #title, yt-formatted-string')?.textContent?.trim();
      const link = el.querySelector('a')?.href;
      const subtitle = el.querySelector('#subtitle, #byline')?.textContent?.trim();
      if (link && !collected.has(link)) {
        collected.set(link, { title, link, subtitle, tag: el.tagName });
      }
    });
  }

  record();

  for (let i = 0; i < 5; i++) {
    window.scrollBy(0, 1000);
    await new Promise(r => setTimeout(r, 800));
    record();
  }

  return Array.from(collected.values());
});

console.log("Total items collected after scrolling:", items.length);
console.log("Playlists / Shows / Channels:", items.filter(x => x.tag !== 'YTK-COMPACT-VIDEO-RENDERER'));
console.log("Any with 'course' in title/subtitle:", items.filter(x => /course/i.test(x.title || '')));
console.log("Any with 'animal' in title/subtitle:", items.filter(x => /animal/i.test(x.title || '')));

